import{_ as n,C as t,o as s,c as d,E as e,a6 as p}from"./chunks/framework.QBF2cGGQ.js";const m=JSON.parse('{"title":"学习中心","description":"","frontmatter":{"layout":"doc","pageClass":"learn-page","title":"学习中心","aside":false},"headers":[],"relativePath":"learn/index.md","filePath":"learn/index.md","lastUpdated":1793513854000}'),i={name:"learn/index.md"};function l(c,o,u,g,h,_){const a=t("LearnHero"),r=t("LearnDashboard");return s(),d("div",null,[e(a),e(r),o[0]||(o[0]=p('<h2 id="这个平台怎么用" tabindex="-1">这个平台怎么用 <a class="header-anchor" href="#这个平台怎么用" aria-label="Permalink to &quot;这个平台怎么用&quot;">​</a></h2><p><strong>1. 按步骤读，不要一次看完。</strong> 每一步结束都有一个&quot;停一下，先回答&quot;的问题。想 30 秒再看下一段，效果比连读三遍好。想不出来是正常的，那正是你该学的地方。</p><p><strong>2. 练习不要靠猜。</strong> 每道题都有三级提示：第一层给思路，第二层给关键线索，第三层才给完整讲解。<strong>直接看第三层等于没做。</strong> 判分后会告诉你为什么对、为什么错、对应哪个知识点。</p><p><strong>3. 编程题是真的在跑。</strong> 代码在独立沙箱 iframe 里执行（拿不到本页面 DOM、cookie、localStorage），通过检查项才算过。Node.js 的 <code>http</code>/<code>fs</code> 这类跑不了，那部分给的是&quot;本地运行说明 + 代码审查&quot;，<strong>不会假装它跑起来了</strong>。</p><p><strong>4. 测试是硬门槛。</strong> 全部练习通过才能解锁掌握测试，测试通过才标记&quot;已掌握&quot;。这不是为了卡你，是因为&quot;我读完了&quot;和&quot;我会了&quot;是两件事，只有测试能区分。</p><p><strong>5. 错了会自动进错题本。</strong> 按 1 → 3 → 7 → 21 天排期复习，做对一次推进一轮，四轮算消化。</p><h2 id="关于-ai-导师" tabindex="-1">关于 AI 导师 <a class="header-anchor" href="#关于-ai-导师" aria-label="Permalink to &quot;关于 AI 导师&quot;">​</a></h2><p>页面底部的&quot;AI 导师&quot;需要你自己跑一个本地代理服务（<code>node server/tutor.mjs</code>），Key 只存在服务端环境变量里。<strong>没配置时会明确显示&quot;未配置&quot;，不会编造回答。</strong> 不配置完全不影响学习——正文、练习、判分、进度都不依赖它。</p><h2 id="现在有什么" tabindex="-1">现在有什么 <a class="header-anchor" href="#现在有什么" aria-label="Permalink to &quot;现在有什么&quot;">​</a></h2><p><strong>24 节课全部写完，没有占位课。</strong> 覆盖 5 个模块组：工程底座（6 节）、模型基础（3 节）、核心能力（6 节）、生产化（5 节）、前沿与交付（4 节）。</p><p>累计 <strong>166 个分步讲解、97 道分级练习、171 道掌握测试题</strong>。每节课都是同一个标准：讲清&quot;是什么 / 为什么 / 怎么做 / 什么时候不该用&quot;，带 Vue 类比、完整代码、常见坑和真实项目落点。</p><p>除了课程，还有 <strong>27 章知识地图 / 1256 个知识点</strong> 作为参考手册——课程负责带你走一遍，地图负责卡住时回查。</p><h2 id="建议顺序" tabindex="-1">建议顺序 <a class="header-anchor" href="#建议顺序" aria-label="Permalink to &quot;建议顺序&quot;">​</a></h2><p>如果你完全没碰过后端，按 01 → 02 → 03 打底，再跳到 05 学模型。</p><p>如果你已经写过 Node 接口，可以从 <strong>05 LLM 基础</strong> 直接开始，遇到类型和数据库的疑问再回补 03 / 04。</p><p>如果你已经在做 AI 应用、只想补生产化，从 <strong>09 评测</strong> 进，然后 10 可观测 → 11 安全 → 12 部署 → 18 成本，这五节是一条完整的上线链路。</p>',16))])}const f=n(i,[["render",l]]);export{m as __pageData,f as default};
